-- Multiple photos per property (gallery / carousel). photo_url stays as the cover image.
alter table leasing.property add column if not exists photos jsonb not null default '[]'::jsonb;

update leasing.property p set photos = jsonb_build_array(
    p.photo_url,
    (array['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&q=80','https://images.unsplash.com/photo-1570129477492-45c003edd2be?w=1200&q=80','https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80','https://images.unsplash.com/photo-1460317442991-0ec209397118?w=1200&q=80','https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=1200&q=80','https://images.unsplash.com/photo-1494526585095-c41746248156?w=1200&q=80'])[1 + (abs(hashtext(p.id::text)) + 1) % 7],
    (array['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&q=80','https://images.unsplash.com/photo-1570129477492-45c003edd2be?w=1200&q=80','https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80','https://images.unsplash.com/photo-1460317442991-0ec209397118?w=1200&q=80','https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=1200&q=80','https://images.unsplash.com/photo-1494526585095-c41746248156?w=1200&q=80'])[1 + (abs(hashtext(p.id::text)) + 3) % 7],
    (array['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1200&q=80','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&q=80','https://images.unsplash.com/photo-1570129477492-45c003edd2be?w=1200&q=80','https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1200&q=80','https://images.unsplash.com/photo-1460317442991-0ec209397118?w=1200&q=80','https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?w=1200&q=80','https://images.unsplash.com/photo-1494526585095-c41746248156?w=1200&q=80'])[1 + (abs(hashtext(p.id::text)) + 5) % 7]
) where p.photo_url is not null and p.photos = '[]'::jsonb;
